import{_ as e,o as i,c as s,a3 as n}from"./chunks/framework.rPoJfhSN.js";const u=JSON.parse('{"title":"Solución de problemas","description":"","frontmatter":{},"headers":[],"relativePath":"operacion/solucion-problemas.md","filePath":"operacion/solucion-problemas.md","lastUpdated":null}'),o={name:"operacion/solucion-problemas.md"};function t(l,a,r,d,c,p){return i(),s("div",null,[...a[0]||(a[0]=[n('<h1 id="solucion-de-problemas" tabindex="-1">Solución de problemas <a class="header-anchor" href="#solucion-de-problemas" aria-label="Permalink to &quot;Solución de problemas&quot;">​</a></h1><h2 id="php-artisan-optimize-falla-por-una-ruta-duplicada" tabindex="-1"><code>php artisan optimize</code> falla por una ruta duplicada <a class="header-anchor" href="#php-artisan-optimize-falla-por-una-ruta-duplicada" aria-label="Permalink to &quot;`php artisan optimize` falla por una ruta duplicada&quot;">​</a></h2><p>Laravel exige que cada ruta nombrada sea única para serializar el caché. Busca el nombre indicado:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route:list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name=admin.password.update</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Renombra o elimina la definición duplicada, luego ejecuta <code>php artisan optimize:clear</code> y vuelve a optimizar.</p><h2 id="opcache-informa-una-api-de-zend-distinta" tabindex="-1">OPcache informa una API de Zend distinta <a class="header-anchor" href="#opcache-informa-una-api-de-zend-distinta" aria-label="Permalink to &quot;OPcache informa una API de Zend distinta&quot;">​</a></h2><p>PHP y la extensión OPcache fueron compilados para APIs diferentes. Instala la DLL o paquete exacto de tu versión de PHP, o desactiva temporalmente esa extensión en desarrollo. Reinicia el servidor y confirma con <code>php --ri opcache</code>.</p><h2 id="aparece-unauthenticated" tabindex="-1">Aparece <code>Unauthenticated</code> <a class="header-anchor" href="#aparece-unauthenticated" aria-label="Permalink to &quot;Aparece `Unauthenticated`&quot;">​</a></h2><p>La petición llegó a una ruta protegida sin una sesión válida. En HTML, redirige al login; en AJAX, maneja el <code>401</code> y conserva el destino deseado. Verifica cookies, dominio de <code>APP_URL</code>, CSRF y el header <code>Accept</code>.</p><h2 id="los-ajustes-no-cambian" tabindex="-1">Los ajustes no cambian <a class="header-anchor" href="#los-ajustes-no-cambian" aria-label="Permalink to &quot;Los ajustes no cambian&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimize:clear</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Los ajustes de negocio se conservan en caché. Evita modificar la tabla directamente salvo mantenimiento controlado.</p><h2 id="docs-no-existe" tabindex="-1"><code>/docs/</code> no existe <a class="header-anchor" href="#docs-no-existe" aria-label="Permalink to &quot;`/docs/` no existe&quot;">​</a></h2><p>Compila el portal:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Confirma que exista <code>public/docs/index.html</code>, que el document root sea <code>public</code> y que el servidor permita archivos estáticos bajo <code>/docs/</code>.</p><h2 id="imagenes-o-descargas-fallan" tabindex="-1">Imágenes o descargas fallan <a class="header-anchor" href="#imagenes-o-descargas-fallan" aria-label="Permalink to &quot;Imágenes o descargas fallan&quot;">​</a></h2><p>Verifica permisos, enlaces simbólicos, rutas almacenadas en base y que el respaldo de archivos corresponda al dump restaurado. No conviertas un disco privado en público para resolver KYC.</p>',18)])])}const m=e(o,[["render",t]]);export{u as __pageData,m as default};
